//! Solid-color endpoint fits from RVA 0x93a60. The grayscale table can be
//! generated by searching all RGB565 endpoint pairs with equal red and blue.

use std::sync::OnceLock;

use super::{BITS, WEIGHTS, expand, pack, source_value};

type Pairs = [Option<[u8; 2]>; 256];

pub(super) fn endpoints(rgb: [u8; 3]) -> [u16; 2] {
    if rgb[0] == rgb[1] && rgb[1] == rgb[2] {
        return gray_table()[usize::from(rgb[0])];
    }
    type Match = ([u8; 2], f64);
    static LOOKUP: OnceLock<[[[Match; 256]; 2]; 2]> = OnceLock::new();
    let lookup = LOOKUP.get_or_init(|| {
        [[1, 0], [1, 2]].map(|[a, b]| {
            [5, 6].map(|bits| {
                let pairs = smallest_spans(bits, a, b);
                std::array::from_fn(|byte| nearest(&pairs, byte as u8))
            })
        })
    });
    let mut best = (f64::INFINITY, [0; 2]);
    for tables in lookup {
        let mut pair = [[0; 3]; 2];
        let mut error = 0.0;
        for channel in 0..3 {
            let table = &tables[usize::from(BITS[channel] - 5)];
            let ([first, second], distance) = table[usize::from(rgb[channel])];
            pair[0][channel] = first;
            pair[1][channel] = second;
            error += (distance * WEIGHTS[channel]).powi(2);
        }
        if error < best.0 {
            best = (error, pair.map(pack));
        }
    }
    best.1
}

fn nearest(pairs: &Pairs, byte: u8) -> ([u8; 2], f64) {
    let target = source_value(byte);
    let (distance, _, pair) = pairs
        .iter()
        .enumerate()
        .filter_map(|(v, p)| {
            p.map(|pair| {
                let v = v as f64;
                ((target - v).abs(), (byte & 1 == 0) == (v > target), pair)
            })
        })
        .min_by(|a, b| a.0.total_cmp(&b.0).then_with(|| a.1.cmp(&b.1)))
        .expect("the endpoint lookup contains black and white");
    (pair, distance)
}

fn smallest_spans(bits: u8, a: u16, b: u16) -> Pairs {
    let mut pairs: Pairs = [None; 256];
    for x in (0..(1 << bits)).rev() {
        for y in (0..(1 << bits)).rev() {
            let ramp = |k| u16::from(expand(k, bits));
            let entry = &mut pairs[((a * ramp(x) + b * ramp(y) + (a + b) / 2) / (a + b)) as usize];
            // The existing endpoints are stored as left-shifted RGB565 codes.
            if entry.is_none_or(|[lo, hi]| {
                ramp(x).abs_diff(ramp(y)) < u16::from(lo.abs_diff(hi)) << (8 - bits)
            }) {
                *entry = Some([x, y]);
            }
        }
    }
    pairs
}

fn gray_table() -> &'static [[u16; 2]; 256] {
    static TABLE: OnceLock<[[u16; 2]; 256]> = OnceLock::new();
    TABLE.get_or_init(|| {
        let tables = [[1, 0], [0, 1], [2, 1], [1, 2]].map(|[a, b]| {
            [5, 6].map(|bits| {
                let mut pairs = [None; 256];
                for x in 0..(1 << bits) {
                    for y in 0..(1 << bits) {
                        let ramp = |k| u16::from(expand(k, bits));
                        let value = ((a * ramp(x) + b * ramp(y)) / (a + b)) as usize;
                        pairs[value].get_or_insert([x, y]);
                    }
                }
                pairs
            })
        });
        std::array::from_fn(|value| {
            let mut best = (u64::MAX, [0; 2]);
            for table in &tables {
                let [(r_error, red), (g_error, green)] = table.each_ref().map(|pairs| {
                    pairs
                        .iter()
                        .enumerate()
                        .filter_map(|(v, pair)| pair.map(|p| (v.abs_diff(value) as u64, p)))
                        .min()
                        .expect("the grayscale lookup contains black and white")
                });
                let error = (3086u64.pow(2) + 820u64.pow(2)) * r_error.pow(2)
                    + 6094u64.pow(2) * g_error.pow(2);
                let mut packed = [
                    pack([red[0], green[0], red[0]]),
                    pack([red[1], green[1], red[1]]),
                ];
                packed.sort_unstable();
                best = best.min((error, packed));
            }
            best.1
        })
    })
}
